function refreshSummaries(){const month=selectedDataMonth(),ffRoutes=state.ffRoutes.filter(r=>routeMonth(r.date)===month&&!isXptBase(r.base)),spotRoutes=state.spotRoutes.filter(r=>routeMonth(r.date)===month&&!isXptBase(r.base)),byBase=Object.fromEntries(aggregateRoutes(ffRoutes).map(r=>[r.base,r])),currentLogic=state.ffLogicSummary.filter(r=>!invalidLogicValue(r.base)&&!isXptBase(r.base)).map(r=>({...r,base:canonicalBase(r.base)})),fallbackLogic=month==='2026-07'?state.snapshotFFSummary.filter(r=>!invalidLogicValue(r.base)&&!isXptBase(r.base)).map(r=>({...r,base:canonicalBase(r.base)})):[],hasValidLogic=currentLogic.some(r=>Number.isFinite(Number(r.ff_share))&&Number(r.ff_share)>0),logicSummary=month==='2026-07'&&fallbackLogic.length&&!hasValidLogic?fallbackLogic:currentLogic,logicByBase=Object.fromEntries(logicSummary.map(r=>[r.base,r]));state.ffSummary=logicSummary.map(r=>{const g=byBase[r.base]||{total:0,ff:0,ambulance:0,ff_ds:null,project:''};const share=Number(r.ff_share??r.utilization);return {...r,total:g.total,ff:g.ff,ambulance:g.ambulance||0,ff_ds:g.ff_ds,ff_share:Number.isFinite(share)?share:null,project:g.project||''}});Object.values(byBase).filter(g=>!logicByBase[g.base]&&!invalidLogicValue(g.base)&&!isXptBase(g.base)).forEach(g=>state.ffSummary.push({...g,ff_share:0}));state.spotSummary=aggregateRoutes(spotRoutes,'spot');state.plateRankings={ff:buildPlateRanking(ffRoutes),spot:buildPlateRanking(spotRoutes)};if(state.mode==='ff'){state.summary=state.ffSummary;state.routes=ffRoutes}else{state.summary=state.spotSummary;state.routes=spotRoutes}spotMetricsCache={routes:null,month:null,metrics:null};refreshMonthOptions();document.querySelector('#routeNavCount')?.replaceChildren(document.createTextNode(state.routes.length.toLocaleString('pt-BR')));document.querySelector('#baseNavCount')?.replaceChildren(document.createTextNode(String(state.summary.length)))}
function applyLogicToRoutes(){refreshLogicSummary();const keys=logicKeys(state.ffLogicRows),sourceByKey=logicSourceByKey(state.ffLogicRows),logicMonths=new Set(state.ffLogicRows.map(r=>routeMonth(r.date)).filter(Boolean)),covered=r=>logicMonths.has(routeMonth(r.date));if(state.ddsRoutes.length){const all=state.ddsRoutes.filter(r=>!r.isAmb&&!isXptBase(r.base)),ddsMonths=new Set(all.map(r=>routeMonth(r.date)).filter(Boolean)),baselineFF=state.snapshotFFRoutes.filter(r=>!ddsMonths.has(routeMonth(r.date))&&!isXptBase(r.base)),baselineSpot=state.snapshotSpotRoutes.filter(r=>!ddsMonths.has(routeMonth(r.date))&&!isXptBase(r.base)),importedFF=keys.size?all.filter(r=>!invalidLogicValue(r.base)&&!invalidLogicValue(r.placa)&&keys.has(routeMatchKey(r))).map(r=>({...r,source_type:sourceByKey.get(routeMatchKey(r))||'LOGICA FF'})):[],ffRouteKeys=new Set(importedFF.map(r=>`${r.date}|${r.rota}|${plateNorm(r.placa)}`)),importedSpot=all.filter(r=>!ffRouteKeys.has(`${r.date}|${r.rota}|${plateNorm(r.placa)}`)&&!isSpotExcluded(r)).map(r=>({...r,source_type:'SPOT'}));state.ffRoutes=[...baselineFF,...importedFF];state.spotRoutes=[...baselineSpot,...importedSpot]}else if(keys.size){const inLogic=r=>!logicMonths.size||covered(r);state.ffRoutes=state.ffRoutes.filter(r=>!isXptBase(r.base)&&(!inLogic(r)||(!invalidLogicValue(r.base)&&!invalidLogicValue(r.placa)&&keys.has(routeMatchKey(r))))).map(r=>inLogic(r)?{...r,source_type:sourceByKey.get(routeMatchKey(r))||r.source_type||'LOGICA FF'}:r);state.spotRoutes=state.spotRoutes.filter(r=>!isXptBase(r.base)&&(!inLogic(r)||!isSpotExcluded(r)))}refreshSummaries()}
function mercadoKey(row){const r=normalized(row),date=logicDate(r.data||r.date||r.dataderota||r.datadarota||r.routedate||r.datadodispatch||r.datadispatch),driver=driverNorm(r.motorista||r.nomemotorista||r.nomedomotorista||r.nomedotransportador||r.nometransportador||r.nomecondutor||r.driver||r.drivername||r.condutor||r.nome||r.transportador),routeId=String(r.rotalogistics||r.iddarota||r.idrota||r.routeid||r.rota||'').trim(),plate=String(r.placa||r.plate||'').trim();return {r,date,driver,routeId,plate,driverKey:date&&driver?`driver|${date}|${driver}`:'',routeKey:date&&routeId?`route|${date}|${plateNorm(routeId)}`:'',plateKey:date&&plate?`plate|${date}|${plateNorm(plate)}`:''}}
function mercadoRowMetrics(r){const successRaw=r.entregacomsucesso??r.entregascomsucesso??r.entregassucesso??r.sucessos??r.successfuldeliveries??'',explicitRaw=r.ds||r.dsrota||r.percentualds||r.deliverysuccessrate||r.performance||r.performanceds||successRaw,explicit=parsePercent(explicitRaw);return {explicit,success:null,total:null}}
