function applyMercadoToRoutes(){if(!state.mercadoRows.length)return;const updates=mercadoUpdates(state.mercadoRows),mercadoMonths=new Set(state.mercadoRows.map(r=>routeMonth(mercadoKey(r).date)).filter(Boolean)),apply=routes=>routes.map(route=>{const date=routeDayKey(route.date),driverKey=`driver|${date}|${driverNorm(route.motorista)}`,routeKey=`route|${date}|${plateNorm(route.rota)}`,plateKey=`plate|${date}|${plateNorm(route.placa)}`,exact=updates.get(driverKey)||updates.get(routeKey)||updates.get(plateKey),ds=exact&&Number.isFinite(exact.ds)?exact.ds:null;if(!mercadoMonths.has(routeMonth(route.date)))return route;return {...route,ds,ds_source:Number.isFinite(ds)?'MERCADO_LIVRE':null}});state.ffRoutes=apply(state.ffRoutes);state.spotRoutes=apply(state.spotRoutes);if(!updates.size)console.error('Mercado Livre carregado, mas nenhum DS foi reconhecido. Verifique os cabeçalhos de data, motorista, rota e Entrega com sucesso.');refreshSummaries()}
async function hydrateLatestImports(){try{const statusResponse=await fetch('/api/imports/status',{cache:'no-store'});if(!statusResponse.ok)return false;const statusSources=(await statusResponse.json()).sources||{},signature=Object.entries(statusSources).sort(([a],[b])=>a.localeCompare(b)).map(([key,value])=>key+':'+(value.importedAt||value.fileName||'')+':'+(value.rowCount||0)).join('|');if(signature&&signature===latestImportsSignature)return false;const response=await fetch('/api/imports/latest',{cache:'no-store'});if(!response.ok)return false;const sources=(await response.json()).sources||{};if(signature)latestImportsSignature=signature;const dds=sources.DDS?.rows,mercado=sources.MERCADO_LIVRE?.rows,logic=sources.LOGICA_FF?.rows,fleet=sources.FF_LOCADORA?.rows;if(Array.isArray(dds)){state.ddsRows=dds;state.ddsRoutes=ddsRoutesFromRows(dds)}if(Array.isArray(mercado))state.mercadoRows=mercado;if(Array.isArray(logic)){state.ffLogicRows=mergeLogicRows(readLogicRows(logic));refreshLogicSummary()}if(Array.isArray(fleet))setFleetReference({master:fleet.map(raw=>{const r=normalized(raw);return {plate:r.plate||r.placa||'',type:fleetType(r.type||r.ffoulocadora)}})});if(Array.isArray(dds)||Array.isArray(mercado)||Array.isArray(logic)||Array.isArray(fleet)){applyLogicToRoutes();if(state.mercadoRows.length)applyMercadoToRoutes();return true}}catch(error){console.warn('Importações salvas não carregadas',error)}return false}
async function readImportSheet(file,matcher){if(!file.name.toLowerCase().endsWith('.xlsx'))return parseCsv(await file.text());if(!window.XLSX)throw new Error('Leitor XLSX indisponível');const book=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:true});const name=book.SheetNames.find(n=>matcher(String(n).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()))||book.SheetNames[0];return XLSX.utils.sheet_to_json(book.Sheets[name],{defval:''})}
async function readFleetReference(file){if(!file.name.toLowerCase().endsWith('.xlsx')){const rows=parseCsv(await file.text());return {master:rows.map(raw=>{const r=normalized(raw);return {plate:r.placa||'',type:fleetType(r.tipo||r.modalidade||r.ffoulocadora)}}).filter(r=>r.plate&&r.type)}}if(!window.XLSX)throw new Error('Leitor XLSX indisponível');const book=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:true}),sheetName=book.SheetNames.find(n=>String(n).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes('ff ou locadora'))||book.SheetNames[0],masterRows=XLSX.utils.sheet_to_json(book.Sheets[sheetName],{defval:''});return {master:masterRows.map(raw=>{const r=normalized(raw);return {plate:r.placa||'',type:fleetType(r.ffoulocadora||r.tipo||r.modalidade)}}).filter(r=>r.plate&&r.type)}}
async function handleDdsImport(e){const input=e.target,file=input.files[0];if(!file)return;setUploadStatus(input,'Lendo planilha DDS…',8,'loading');try{const rows=await readImportSheet(file,n=>n.includes('geral'));state.ddsRows=rows;state.ddsRoutes=ddsRoutesFromRows(rows);setUploadStatus(input,'Arquivo lido. Enviando para o painel…',18,'loading');const stored=await persistImport(file,'DDS',rows,input);applyLogicToRoutes();applyMercadoToRoutes();render();setUploadStatus(document.querySelector('#ddsInput'),'Upload DDS concluído',100,'success');toast(rows.length.toLocaleString('pt-BR')+' linhas DDS carregadas · '+stored.recordsUpserted.toLocaleString('pt-BR')+' salvas no banco.')}catch(error){console.error(error);setUploadStatus(input,'Não foi possível concluir o upload DDS',100,'error');toast('Não foi possível ler a planilha DDS.')}}
async function handleMercadoImport(e){const input=e.target,file=input.files[0];if(!file)return;setUploadStatus(input,'Lendo planilha Mercado Livre…',8,'loading');try{const rows=await readImportSheet(file,n=>n.includes('entrega')&&(n.includes('sucesso')||n.includes('success')));state.mercadoRows=rows;setUploadStatus(input,'Arquivo lido. Enviando para o painel…',18,'loading');const stored=await persistImport(file,'MERCADO_LIVRE',rows,input);applyMercadoToRoutes();render();setUploadStatus(document.querySelector('#mercadoInput'),'Upload Mercado Livre concluído',100,'success');toast(rows.length.toLocaleString('pt-BR')+' registros de entregas com sucesso carregados · '+stored.recordsUpserted.toLocaleString('pt-BR')+' salvos no banco.')}catch(error){console.error(error);setUploadStatus(input,'Não foi possível concluir o upload Mercado Livre',100,'error');toast('Não foi possível ler a aba de entregas com sucesso do Mercado Livre.')}}
async function handleLogicImport(e){const input=e.target,file=input.files[0];if(!file)return;setUploadStatus(input,'Lendo planilha LOGICA FF…',8,'loading');try{const rows=await readImportSheet(file,n=>n==='dados');state.ffLogicRows=mergeLogicRows(readLogicRows(rows));refreshLogicSummary();setUploadStatus(input,'Arquivo lido. Enviando para o painel…',18,'loading');const stored=await persistImport(file,'LOGICA_FF',rows,input);applyLogicToRoutes();if(state.mercadoRows.length)applyMercadoToRoutes();render();setUploadStatus(document.querySelector('#logicInput'),'Upload LOGICA FF concluído',100,'success');toast(state.ffLogicRows.length.toLocaleString('pt-BR')+' registros de utilização FF carregados · '+stored.recordsUpserted.toLocaleString('pt-BR')+' salvos no banco.')}catch(error){console.error(error);setUploadStatus(input,'Não foi possível concluir o upload LOGICA FF',100,'error');toast('Não foi possível ler a aba DADOS da LOGICA FF.')}}
