state.dispatcherReference={bases:{}};state.teamConfigs={};state.invoices=[];state.expandedBases=new Set();state.routeRank='all';state.routeBase='';
function workspaceTeamKey(base){return baseNorm(canonicalBase(base))}
function workspaceTeam(base){const key=workspaceTeamKey(base),ref=state.dispatcherReference.bases[key]||{},saved=state.teamConfigs[key]||{};return {base:canonicalBase(base),coordinator:saved.coordinator||ref.coordinator||'',dispatchers:Object.prototype.hasOwnProperty.call(saved,'dispatchers')?saved.dispatchers:(ref.dispatchers||[]),ffRecipient:saved.ffRecipient||''}}
