function workspaceRouteRows(rows){const rank=state.routeRank||'all',groupByDriver=rank.toLowerCase().includes('driver'),keyOf=row=>groupByDriver?(driverNorm(row.motorista)||'SEM MOTORISTA'):String(row.base||'Base sem nome'),groups=new Map();if(rank==='all')return [...rows];rows.forEach(row=>{const key=keyOf(row),item=groups.get(key)||{count:0,eligible:0,dsSum:0,dsCount:0};const ds=numericValue(row.ds);item.count++;if(Number.isFinite(ds)){item.dsSum+=ds;item.dsCount++;if(ds>=.92)item.eligible++}groups.set(key,item)});const average=item=>item.dsCount?item.dsSum/item.dsCount:null,ranked=[...groups.entries()].sort((a,b)=>{const [ak,as]=a,[bk,bs]=b,ads=average(as),bds=average(bs),aValue=ads===null?Infinity:ads,bValue=bds===null?Infinity:bds;if(rank==='topDriver'||rank==='topBase')return bValue-aValue||bs.count-as.count||ak.localeCompare(bk,'pt-BR');if(rank==='bottomDriver')return aValue-bValue||bs.count-as.count||ak.localeCompare(bk,'pt-BR');if(rank==='attentionDriver'||rank==='attentionBase')return (bs.count-bs.eligible)-(as.count-as.eligible)||aValue-bValue||ak.localeCompare(bk,'pt-BR');if(rank==='volumeDriver')return bs.count-as.count||bValue-aValue||ak.localeCompare(bk,'pt-BR');return 0}),order=new Map(ranked.map(([key],index)=>[key,index]));return [...rows].sort((a,b)=>{const groupDelta=order.get(keyOf(a))-order.get(keyOf(b));if(groupDelta)return groupDelta;const ads=numericValue(a.ds),bds=numericValue(b.ds),aValue=Number.isFinite(ads)?ads:Infinity,bValue=Number.isFinite(bds)?bds:Infinity;return rank==='topDriver'||rank==='topBase'?bValue-aValue:aValue-bValue})}
