function previousMonth(month){const [year,value]=String(month||'').split('-').map(Number);if(!year||!value)return '';const date=new Date(Date.UTC(year,value-2,1));return `${date.getUTCFullYear()}-${String(date.getUTCMonth()+1).padStart(2,'0')}`}
