function comparisonRows(){const currentMonth=selectedDataMonth(),priorMonth=previousMonth(currentMonth),currentMap=new Map(comparisonDataForMonth(currentMonth,true).map(row=>[workspaceTeamKey(row.base),row])),priorMap=new Map(comparisonDataForMonth(priorMonth,false).map(row=>[workspaceTeamKey(row.base),row])),keys=new Set([...currentMap.keys(),...priorMap.keys()]);return [...keys].map(key=>{const current=currentMap.get(key)||null,prior=priorMap.get(key)||null,dsDelta=current&&prior&&Number.isFinite(current.ds)&&Number.isFinite(prior.ds)?current.ds-prior.ds:null,bonusDelta=current&&prior?current.bonus-prior.bonus:null,totalDelta=current&&prior?current.total-prior.total:null;return {base:current?.base||prior?.base||key,current,prior,dsDelta,bonusDelta,totalDelta,status:dsDelta===null?'Sem histórico':dsDelta>=.5?'Evolução':dsDelta<=-.5?'Piora':'Estável'}}).sort((a,b)=>{const sort=state.comparisonSort||'evolution';if(sort==='decline')return (a.dsDelta??Infinity)-(b.dsDelta??Infinity);if(sort==='bonus')return (b.current?.bonus||0)-(a.current?.bonus||0);if(sort==='volume')return (b.current?.total||0)-(a.current?.total||0);if(sort==='name')return String(a.base).localeCompare(String(b.base),'pt-BR');return (b.dsDelta??-Infinity)-(a.dsDelta??-Infinity)})}
